    "Scala/GraalVM/JIT": "sbt 'assembly'",
    "Dart/AOT": "dart compile exe main.dart -o target/dart_benchmark",
    "Dart/JIT": "true",
    "TypeScript/Node/Default": "sh -c 'npm install; npm run build:run --silent'",
    "TypeScript/Bun/JIT": "true",
    "TypeScript/Bun/Compiled": "bun build --target=bun --outdir=target/dist-bun src/index.ts",
    "TypeScript/Deno/Default": "true",
